test("publisher evidence binds rights, editorial and validation to current trust",async()=>{
 const {requirePublisherEvidence}=await import("../src/content-admin/authorization"); const now=Date.now();
 const subject={kind:"profile-append" as const,namespace:"ns",projectId:"project",identityId:"i",identityPolicyRevision:"1",identityPolicyHash:"9".repeat(64),profileScope:"scope",pointerVersion:null,profileSourceId:"p",profileRevision:"1",profileRawId:"raw",profileHash:sha(bytes("profile")),snapshotId:"snapshot",snapshotProvenanceHash:"8".repeat(64),snapshotHash:"b".repeat(64),releaseId:"r",releaseRoot:"c".repeat(64),receiptId:"receipt",catalogId:"catalog",catalogRoot:"d".repeat(64),sealHash:"e".repeat(64),categories:["c"]};
 const purposes=["rights","editorial","validation","semantic","custody"] as const;const trust={namespace:"ns",projectId:"project",policyId:"policy",revision:"1",hash:"f".repeat(64),validFrom:now-1000,validUntil:now+60000,maxAgeMs:30000,versions:["v1"],revokedEvidenceIds:[] as string[],issuers:purposes.map(purpose=>({purpose,issuerId:"issuer",keyId:"key",trustRootId:"root"}))};
 const proof={purposes:[...purposes],status:"verified",evidenceVersion:"v1",evidenceId:"proof",evidenceHash:"a".repeat(64),issuerId:"issuer",keyId:"key",trustRootId:"root",policyId:"policy",policyRevision:"1",policyHash:trust.hash,validatedAt:now,validUntil:now+30000,subject};const authority={readCurrentPolicy:async()=>trust,verify:async()=>proof};
 await requirePublisherEvidence(subject,authority,bytes("profile"));await assert.rejects(()=>requirePublisherEvidence({...subject,profileScope:"other"},authority,bytes("profile")));await assert.rejects(()=>requirePublisherEvidence(subject,{...authority,readCurrentPolicy:async()=>({...trust,revokedEvidenceIds:["proof"]})},bytes("profile")));await assert.rejects(()=>requirePublisherEvidence(subject,undefined,bytes("profile")));
});
