test("registry commit dispatches once and replay cannot repeat SDK effects",async()=>{
 const {changeRegistry}=await import("../src/content-admin/service");
 const desired={namespace:"ns",projectId:"project",identityId:"target",authzVersion:2,enabled:true,disabled:false,roles:["reviewer"],categoryScopes:["c"],reviewerScopes:["fact_reviewer"]};
 const desiredHash=sha(bytes(canonicalJson(desired))); const receipt={operationId:"op",revision:2,status:"registry_committed"}; let mutations=0,sets=0,completions=0;
 const io={transactionMode:"autocommit" as const,query:async(sql:string)=>{if(sql.includes("rate_take")) return {rows:[{result:{count:1}}] as never}; if(sql.includes("registry_change")) return {rows:[{result:++mutations===1?{receipt,replayed:false,desired:{...desired,desiredAuthorizationHash:desiredHash}}:{receipt,replayed:true,sync:{status:"identity_synced",revision:2}}}] as never}; if(sql.includes("sync_complete")) {completions++;return {rows:[{result:{status:"identity_synced"}}] as never};} throw new Error("unexpected query");}};
 const repo=testRepository(io); let customClaims:Record<string,unknown>={unrelated:true};
 const auth={app:{options:{projectId:"project"}},getUser:async()=>({uid:"target-uid",disabled:false,emailVerified:true,providerData:[{providerId:"password"}],customClaims}),setCustomUserClaims:async(_uid:string,claims:Record<string,unknown>)=>{sets++;customClaims=claims;},updateUser:async()=>{throw new Error("unexpected update");},revokeRefreshTokens:async()=>{}};
 const claims={namespace:"ns",projectId:"project",uid:"actor",identityId:"actor-id",claimRoles:["super_admin"] as const,claimAuthzVersion:1,provider:"password" as const,policyRevision:"1",policyHash:"f".repeat(64)};
 const deps={resolveIdentity:async()=>"target",sync:{auth:auth as never,settlement:{verify:async(intent:import("../src/content-admin/service").SyncIntent,outcome:"identity_synced"|"identity_sync_failed")=>({...intent,outcome,settled:true,evidenceHash:"e".repeat(64)})},completion:{complete:async(intent:import("../src/content-admin/service").SyncIntent,proof:import("../src/content-admin/service").SettledSyncProof)=>repo.syncComplete(intent.namespace,intent.operationId,intent.identityId,intent.authzVersion,intent.desiredAuthorizationHash,proof.outcome,proof.evidenceHash)}}};
 const request={targetUid:"target-uid",operationId:"op",expectedRevision:1,mode:"role" as const,payload:{enabled:true,roles:["reviewer"],categoryScopes:["c"],reviewerScopes:["fact_reviewer"]}};
 await changeRegistry(repo,claims,deps,request); await changeRegistry(repo,claims,deps,request);
 assert.equal(sets,1); assert.equal(completions,1); assert.equal(customClaims.unrelated,true);
});

test("sync failure needs exact settled proof; stale proof cannot complete",async()=>{
 const {synchronizeIdentity}=await import("../src/content-admin/service");
 const intent={namespace:"ns",projectId:"project",identityId:"target",uid:"uid",operationId:"op",authzVersion:2,enabled:true,disabled:false,roles:["reviewer"],categoryScopes:["c"],reviewerScopes:["fact_reviewer"],desiredAuthorizationHash:"a".repeat(64)};
 let completions=0;
 const auth={app:{options:{projectId:"project"}},getUser:async()=>{throw new Error("sdk failure");},setCustomUserClaims:async()=>{},updateUser:async()=>{},revokeRefreshTokens:async()=>{}};
 const completion={complete:async()=>{completions++;}};
 await assert.rejects(()=>synchronizeIdentity(intent,auth as never,undefined,completion),/SYNC_AUTHORITY_UNAVAILABLE/);
 await assert.rejects(()=>synchronizeIdentity(intent,auth as never,{verify:async(i,outcome)=>({...i,authzVersion:3,outcome,settled:true,evidenceHash:"b".repeat(64)})},completion),/SYNC_AUTHORITY_UNAVAILABLE/);
 assert.equal(completions,0);
 await synchronizeIdentity(intent,auth as never,{verify:async(i,outcome)=>({...i,outcome,settled:true,evidenceHash:"b".repeat(64)})},completion);
 assert.equal(completions,1);
});
