test("source inventory isolates material, publisher and catalog lock order",async()=>{
 const {readFileSync}=await import("node:fs");const sql=readFileSync("services/enta/server/prisma/migrations/20261027210000_eng03_05_content_admin_boundary/migration.sql","utf8"),roles=readFileSync("services/enta/server/prisma/roles/eng03_05_content_admin_roles.sql","utf8");
 const declarations=[...sql.matchAll(/CREATE FUNCTION public\.eng03_05_([a-z0-9_]+)\(/g)].map(x=>x[1]);assert.equal(declarations.length,48);assert.equal(new Set(declarations).size,48);
 for(const name of declarations)assert.match(roles,new RegExp(`public\\.eng03_05_${name}\\(`));
 const grants=[...roles.matchAll(/^GRANT EXECUTE ON FUNCTION public\.eng03_05_media_append\([^\r\n]+ TO ([a-z0-9_]+);$/gm)].map(x=>x[1]);assert.deepEqual(grants,["huroof_pg_material_executor"]);
 for(const name of ["snapshot_read","profile_prepare","pointer_prepare","profile_append","pointer_move"]){const start=sql.indexOf(`CREATE FUNCTION public.eng03_05_${name}(`),end=sql.indexOf("END $$;",start),body=sql.slice(start,end);assert.ok(start>=0 && end>start);const catalog=body.indexOf('FROM public."ActiveCatalogPointer" WHERE "id"=\'singleton\' FOR SHARE'),pointer=body.indexOf('FROM public."HuroofContentPointer"');assert.ok(catalog>=0 && pointer>catalog,`${name} catalog before pointer`);}
 assert.match(sql,/last usable super admin/);assert.match(sql,/identityReady"=false/);assert.match(sql,/release-question-document-raw-sha256-v1/);assert.match(roles,/unexpected privileged role member/);
 const grantPairs=[...roles.matchAll(/^GRANT EXECUTE ON FUNCTION (public\.eng03_05_[a-z0-9_]+\([^\r\n]+?\)) TO ([a-z0-9_]+);$/gm)];assert.equal(grantPairs.length,43);for(const [,signature,role] of grantPairs){const escaped=signature.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");assert.ok(roles.includes(`('${signature}','${role}')`),`allowlist ${signature} ${role}`);assert.ok(escaped.length>0);}assert.match(roles,/missing required routine execute grant/);
});
