test("simulated serialized last-super decision never disables both usable supers",async()=>{
 // This is an explicit schedule model, not execution or proof of PostgreSQL locks.
 const ready=new Set(["a","b"]);let tail=Promise.resolve();const mutate=(id:string)=>{const turn=tail.then(()=>{if(ready.has(id) && ready.size<=1)return false;ready.delete(id);return true;});tail=turn.then(()=>{});return turn;};const results=await Promise.all([mutate("a"),mutate("b")]);assert.equal(results.filter(Boolean).length,1);assert.equal(ready.size,1);
});
